900	// ---- continuous-ring work-item decode (shared by the persistent producer & consumers) ----
901	// One linear work index -> (bi, hk, m_block) + the per-tile bounds. Producer and consumers call this
902	// with the SAME work index so they agree on n_cnt (and thus the global ring counter g advances in
903	// lock-step). Mirrors the per-tile prefill_kernel coordinate/bounds math, minus split-KV (prefill
904	// runs num_splits==1). m_block is LPT-reversed (largest causal tile first) for static-strided balance.
905	struct PfTile {
906	    bool valid;
907	    int q0, hk, bi, seqlen_q, seqlen_k, Mrows, row0, delta, n_lo, n_cnt;
908	    float sc_eff, s2, vd;
909	};
910	template <int CN, int CM, bool EXTRA>
911	__device__ __forceinline__ PfTile pf_work(
912	        int work, int tiles_m, int hkv, int rep, int batch,
913	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
914	        int causal, int win_l, int win_r, float scale,
915	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
916	        const float* __restrict__ v_descale, int ds_b, int ds_h) {
917	    PfTile t; t.valid = false;
918	    (void)batch;
919	    // Per-head LPT (m_block LPT-reversed WITHIN each (bi,hk)): consecutive work-items are same-head
920	    // adjacent m_blocks whose causal key ranges OVERLAP, so the continuous K/V ring + L2 reuse across them.
921	    // (Global-LPT -- m_block slowest across all heads -- cut the makespan tail on large4k but DESTROYED that
922	    // per-head K/V reuse and regressed hd256 0.88->0.79, hd192_dv128 0.94->0.87, seq16k 0.95->0.90. Reverted.)
923	    const int hb = tiles_m * hkv;
924	    const int bi = work / hb;
925	    const int rem = work - bi * hb;
926	    t.hk = rem / tiles_m;
927	    const int m_block = (tiles_m - 1) - (rem - t.hk * tiles_m);
928	    t.bi = bi;
929	    t.q0 = cu_q[bi];
930	    t.seqlen_q = cu_q[bi + 1] - t.q0;
931	    t.seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
932	    t.Mrows = t.seqlen_q * rep;
933	    t.row0 = m_block * CM;
934	    if (t.row0 >= t.Mrows || t.seqlen_k <= 0) return t;            // padded m_block / empty seq
935	    t.delta = t.seqlen_k - t.seqlen_q;
936	    const long ds_idx = (long)bi * ds_b + (long)t.hk * ds_h;
937	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
938	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
939	    t.vd = v_descale ? v_descale[ds_idx] : 1.f;
940	    t.sc_eff = scale * qd * kd;
941	    t.s2 = t.sc_eff * float(M_LOG2E);
942	    const int top = (t.row0 + CM - 1 < t.Mrows - 1) ? (t.row0 + CM - 1) : (t.Mrows - 1);
943	    const int qabs_max = (top / rep) + t.delta;
944	    int n_max = causal ? ((qabs_max + 1 + CN - 1) / CN) : ((t.seqlen_k + CN - 1) / CN);
945	    int n_beg = 0;
946	    if constexpr (EXTRA) {
947	        if (win_l >= 0) { int lo = (t.row0 / rep) + t.delta - win_l; if (lo > 0) n_beg = lo / CN; }
948	        if (!causal && win_r >= 0) { int tt = (qabs_max + win_r) / CN + 1; if (tt < n_max) n_max = tt; }
949	    }
950	    if (n_beg >= n_max) return t;                                  // fully masked
951	    t.n_lo = n_beg; t.n_cnt = n_max - n_beg;
952	    t.valid = true;
953	    return t;
954	}
