977	// Single-split (num_splits==1) analogue of emit_empty_lse for a fully-masked / empty / padded tile:
978	// write 0 to O and -inf to LSE for the tile's valid rows. Without this a fully-masked m-tile (causal
979	// q>>k: every row's qabs < 0 -> n_max==0 -> empty_cta) would `return` before the mainloop, leaving its
980	// O rows at the uninitialized at::empty value (garbage). FA3 returns 0 for such rows. The
981	// (cwg/warp/group, tg) -> (qidx,qhead,dv) mapping mirrors the epilogue exactly.
982	template <typename TC, int HDV>
983	__device__ __forceinline__ void emit_zero_o(TC* __restrict__ O, float* __restrict__ LSE, int tid,
984	        int row0, int Mrows, int hk, int rep, int q0, int total_q, long o_row, long o_head) {
985	    if (tid < WG) return;                              // producer warpgroup carries no rows
986	    const int cwg = tid / WG - 1, wt = tid % WG, wp = wt >> 5, ln = wt & 31;
987	    const int group = ln >> 2, tg = ln & 3;
988	    const int row_lo = cwg * 64 + wp * 16 + group, row_hi = row_lo + 8;
989	    const uint32_t z = pack_2x<TC>(0.f, 0.f);
990	#pragma unroll
991	    for (int r = 0; r < 2; ++r) {
992	        const int idx = row0 + (r == 0 ? row_lo : row_hi);
993	        if (idx >= Mrows) continue;
994	        const int token = idx / rep, qhead = hk * rep + idx % rep, qidx = q0 + token;
995	        const long obase = (long)qidx * o_row + (long)qhead * o_head;
996	#pragma unroll
997	        for (int c = 0; c < HDV / 8; ++c) *reinterpret_cast<uint32_t*>(&O[obase + 8 * c + 2 * tg]) = z;
998	        if (tg == 0) LSE[(long)qhead * total_q + qidx] = -INFINITY;
999	    }

